insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('andros-bahamas', '11C', 'Andros', 'Bahamas', 'The Bahamas'' wild frontier', 'live', 'verified', 'oceanAerial', 'Bahamas', '{"diveglobal","tropical","adventure","wildlife","romance"}', '{}', '{"premier","ultra"}', null, null, '{"key_facts":["Great Andros Barrier Reef - 124 miles (widely cited 3rd-longest - verify)","Tongue of the Ocean drop-off - deep-trench wall dives + pelagics","Blue holes - tidal freshwater sinkholes; 100+ off South Andros","Small Hope Bay Lodge + Andros Beach Club (land-based dive lodges)","World-class bonefishing; no liveaboard fleet; malaria none; hurricane Jun-Nov peak Aug-Oct"],"safety":{"emergency":"911 / 919","hospital":"local clinics; Nassau referral","malaria":"NONE","yellow_fever":"only if arriving from an endemic country","hurricane":"Jun-Nov, peak Aug-Oct","dive_no_fly":"18-24h (DAN); blue-hole/cave = advanced only","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-09-01T16:20:19Z","page_updated":"2026-05-28T17:01:45+01:00","source_country":"bahamas","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":null,"jewels":[{"name":"Tongue of the Ocean wall dive (Small Hope Bay Lodge)","blurb":"CARRIED from the earlier dossier, re-sourced from a guide site (takeyourbackpack.com) to the operator''s own page: \"stunning wall dives at the edge of the continental shelf\"; \"The Tongue of the Ocean - a deep ocean trench that drops over 6,000 feet - begins right offshore, offering world-class diving without long boat rides.\" Published: one-tank $125, two-tank $150, night/shark dive $125 (minimum 6 divers), boat snorkel $50","si":["diveglobal","ocean","adventure"],"commission":"operator","wells":["activities","move","stay"],"draw_rank":4,"fit_rules":{"duration":"one-tank or two-tank boat dive","before":"certification; PADI or SSI Open Water $300 offered on site","after":"no fly-after rule stated on the page","pairs_with":"Andros Barrier Reef coral formations, blue holes, shark dives","time_season":"not stated on the page"},"tier_absent_reason":"does-not-compete","source":"https://www.smallhope.com/diving","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Andros Beach Club - Blue Hole Tours","blurb":"CARRIED from the earlier dossier (\"Andros blue-hole dive\") and re-read today: \"guided snorkeling and diving tours of the Andros Blue Holes\" including Stargate Blue Hole and El Dorado, \"tidal freshwater blue holes\" on \"a major fault line of blue holes running over 50 miles through South Andros\"; also \"Barb''s Nature Walk and Blue Hole Tour\", a guided hike to inland blue holes. No duration or price on the page","si":["diveglobal","adventure","hiking","ocean"],"commission":"operator","wells":["activities"],"draw_rank":5,"tier_absent_reason":"does-not-compete","source":"https://www.androsbeachclub.com/blue-hole-tours/","accessed":"2026-10-03"},{"name":"Andros Barrier Reef","blurb":"Ministry of Tourism: \"The world''s 3rd largest barrier reef\", \"190 miles long\"; it \"drops to about eight feet on the island side and approximately 6,000 feet in the Tongue of the Ocean.\" CARRIED from the earlier dossier and re-read today: the earlier \"124-mi\" length is the figure Small Hope Bay Lodge still uses; bahamas.com now states 190 miles, and both are quoted rather than reconciled","si":["diveglobal","tropical","ocean","wildlife"],"wells":["activities","stay"],"draw_rank":1,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/natural-wonders/andros-barrier-reef","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Captain Bill''s Blue Hole","blurb":"Ministry of Tourism: \"Just follow the winding trail until you reach a clearing, and you can''t miss Captain Bill''s.\" \"A deck hangs over the water''s edge so, go ahead, jump right in.\" Bahamas National Trust: \"nearly perfectly round\" with \"a depth of 100+ feet\", a gazebo and a staircase into the water; \"No entry fee\" - but the BNT page reads \"Closed temporarily\" on the date read","si":["adventure","tropical","family","hiking"],"wells":["activities"],"draw_rank":2,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/andros/blue-holes-national-park/","accessed":"2026-10-03","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Small Hope Bay Lodge","blurb":"\"a historic, intimate, and eco-friendly resort\", founded 1960, all-inclusive beachfront cabins with \"All Meals and Open Bar\", bikes, kayaks, diving and snorkelling lessons, nature tours and complimentary babysitting; published all-inclusive daily rates: adult $375 low season, $425 high season, kids (2-12) $135, under 2 free; 855-841-6966, info@smallhope.com","si":["diveglobal","tropical","family","romance"],"commission":"hotel","wells":["stay","eat","activities"],"draw_rank":3,"tier_absent_reason":"not-established","source":"https://www.smallhope.com/packages","accessed":"2026-10-03"},{"name":"Andros Beach Club","blurb":"\"all-inclusive boutique resort on South Andros Island\" at Kemp''s Bay on four miles of beach; six room types from the Sand Dollar Studio (sleeps 2) to the Coconut Villa (sleeps 6, 1,730 sq ft); bonefishing, \"40+ dive sites and blue holes\", spearfishing, snorkelling and mangrove kayaking","si":["tropical","diveglobal","adventure","family"],"commission":"hotel","wells":["activities","eat","shop","stay"],"draw_rank":6,"tier_absent_reason":"not-established","source":"https://www.androsbeachclub.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Kamalame Cay","blurb":"\"A Private Island Escape Edged by The Andros Great Barrier Reef\": \"a 96-acre cay\" of oceanfront cottages, bungalows and villas, \"accessible via private ferry or seaplane\", with what it calls \"the only overwater spa in the Bahamas\", a freshwater pool and a three-mile beach; dining \"a la carte or all inclusive\"; (800) 790-7971, info@kamalame.com","si":["romance","tropical","wellness"],"commission":"hotel","wells":["activities","beauty","eat","move","stay"],"draw_rank":7,"tier_absent_reason":"not-established","source":"https://www.kamalame.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bonefishing on Andros","blurb":"Ministry of Tourism: \"North Andros is separated from Central Andros by creeks and flats stocked with bonefish.\" \"Tarpon, permit, and bonefish swim these waters. They''re easy to miss, and fishing for them requires a trained eye.\" The page names local guides only by first name and lists no operator","si":["adventure","ocean","wildlife"],"wells":["activities"],"draw_rank":8,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/experiences/fly-fishing-andros","accessed":"2026-10-03","commission":"guide (fishing guide or lodge package) - operator","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - bonefishing is sold by licensed guides and fishing lodges"},{"name":"Andros Island Bonefish Club","blurb":"Cargill Creek; operating \"over 40 years\", built and managed by Captain Rupert Leadon for over 35 years; packages include lodging, guides and meals; published per person double: 3 nights/2 days $2,268 to 8 nights/7 days $6,468, with 6 nights/5 days $4,790 marked most popular; 242-357-2212, info@androsbonefishing.com","si":["adventure","ocean"],"commission":"hotel","wells":["stay","activities","eat"],"draw_rank":9,"tier_absent_reason":"not-established","source":"https://www.androsbonefishing.com/","accessed":"2026-10-03"},{"name":"Mangrove Cay Club","blurb":"\"the Bahamas'' premier saltwater fly fishing lodge. Located smack in the middle of the Andros fishery, the largest area of bonefish habitat in the world\"; \"3, 5 or 7 Night Bonefishing Getaway\" packages with \"full-time professional guides\"; +1.242.369.0731, info@mangrovecayclub.com","si":["adventure","ocean"],"commission":"hotel","wells":["stay","activities","eat"],"draw_rank":10,"tier_absent_reason":"not-established","source":"https://www.mangrovecayclub.com/","accessed":"2026-10-03"},{"name":"Swain''s Cay Lodge","blurb":"\"Bonefishing Lodge and Island Hotel\" on Mangrove Cay with an Orvis-endorsed fly-fishing programme; duplex apartment, ocean-view rooms and suites and a beach-front suite; +1 242-422-5018, fish@swainscaylodge.com","si":["adventure","tropical","ocean"],"commission":"hotel","wells":["stay","activities"],"draw_rank":11,"tier_absent_reason":"not-established","source":"https://www.swainscaylodge.com/","accessed":"2026-10-03"},{"name":"West Side National Park","blurb":"Bahamas National Trust: \"This 1.5 million-acre national park encompasses virtually the entire west side of Andros Island\"; refuge for \"the Andros Rock Iguana, Atala Hairstreak Butterfly, the West Indian Flamingo, Smalltooth Sawfish, and Sea Turtles\"; nursery flats for bonefish and tarpon; \"one of the best flats-fishing areas in the world\"; \"only accessible by boat\" with \"little infrastructure\"","si":["wildlife","adventure","expedition"],"wells":["activities","move","stay"],"draw_rank":12,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/andros/west-side-national-park/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"Blue Holes National Park","blurb":"Bahamas National Trust, North Andros, 40,000 acres, established 2002: \"22 unique inland blue holes, and the surrounding rich coppice and pineland forests\", home to the endemic Bahama Oriole and the Great Lizard Cuckoo; \"No entry fee\"; reads \"Closed temporarily\" on the date read","si":["hiking","wildlife","adventure"],"wells":["activities"],"draw_rank":13,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/andros/blue-holes-national-park/","accessed":"2026-10-03","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"North & South Marine Parks","blurb":"Bahamas National Trust, North Andros, 5,000 acres, established 2002: \"Protects: Coral Reefs & Andros'' Barrier reef\"","si":["diveglobal","ocean","wildlife"],"wells":["activities"],"draw_rank":14,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/andros/","accessed":"2026-10-03","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Androsia Batik","blurb":"\"Androsia Hand Made Batik was established by the Birch family in 1960 on Andros Island\" (androsia.com); the Ministry of Tourism calls batik \"the unofficial national fabric of The Bahamas\" and describes factory tours where visitors \"create their very own Bahamian batik right where it all began\". Factory in Andros Town; +1 242-376-9339; online shop at androsia.com","si":["culture","family"],"commission":"venue","wells":["shop","activities"],"draw_rank":15,"tier_absent_reason":"does-not-compete","source":"https://www.androsia.com/","accessed":"2026-10-03"},{"name":"All Andros Crab Fest","blurb":"At the \"Festival Site, Fresh Creek Central Andros\": \"Bahamian cultural competitions, entertainment and all the crab you can eat\", with \"hundreds of crabs ... cooked in over 100 ways\", crabbing, dominoes, cane peeling and dance competitions; the festival \"began in 1997\". The Ministry''s news page gives \"June 13-14\" for the 18th edition and prints no year; no 2026 or 2027 date was found","si":["culinary","culture","family","entertainment"],"commission":"venue","wells":["activities","eat"],"draw_rank":16,"tier_absent_reason":"does-not-compete","source":"https://www.tourismtoday.com/news/catch-crabs-crawling","accessed":"2026-10-03"},{"name":"All Andros & Berry Islands Regatta","blurb":"Traditional Bahamian sloops race in A, B and C classes at \"Regatta Village in Morgan''s Bluff, North Andros (20 miles from San Andros Airport)\", with Bahamian food and music; listed July 9-11, 2020, contact Mr. Floyd Newton (242) 329-2278. Earlier edition July 4-7, 2019 (ewnews.com); the 2023 All Andros Regatta ran July 13-16 with the Bahamas Games (The Tribune). No 2026 date found","si":["sailing","culture","spectator"],"wells":["activities","eat","fly","stay"],"draw_rank":17,"tier_absent_reason":"not-sold","source":"https://www.tourismtoday.com/events/all-andros-berry-islands-regatta","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"event (free to attend) - pair with Stay-Well and an event-week package","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a festival or regatta - free to attend; the stay and the package around it are the paid route"},{"name":"Crab Replenishment Reserve","blurb":"Bahamas National Trust, North Andros, 4,000 acres, established 2002: \"Protects: Important crab breeding grounds\"","si":["wildlife","expedition"],"wells":["activities"],"draw_rank":18,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/andros/","accessed":"2026-10-03","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"Hank''s Place Restaurant & Bar","blurb":"\"Our restaurant is unlike any other in Andros, because of its unique dining room and bar built over the water, providing guests a stunning view of Fresh Creek''s harbor.\" \"Open Monday through Saturday 2:00 p.m.-10:00 p.m.\" Queen''s Highway, Fresh Creek; (242) 368-2447, hanksplace2@outlook.com","si":["culinary","tropical"],"commission":"venue","wells":["eat","stay"],"draw_rank":19,"tier_absent_reason":"does-not-compete","source":"https://www.bahamas.com/vendor/hanks-place-restaurant-bar","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Shine''s Conch Shack","blurb":"Bahamas Out Island Promotion Board guide (April 27, 2018), northern Mangrove Cay: \"Bahamian delights such as conch salad and crack conch, in addition to chicken wings, lobster ceviche\". A guide-site source: no own page found, and the 2018 date is stated","si":["culinary","culture"],"commission":"venue","wells":["activities","eat"],"draw_rank":20,"tier_absent_reason":"does-not-compete","source":"https://myoutislands.com/blog/boi-news/awaken-your-taste-buds-in-andros","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)"},{"name":"Brigadier''s Restaurant","blurb":"Bahamas Out Island Promotion Board guide (April 27, 2018), Davis Creek: \"try the lobster fritters, or a loaded hamburger at Brigadier''s Restaurant\". A guide-site source: no own page found, and the 2018 date is stated","si":["culinary"],"commission":"venue","wells":["activities","eat"],"draw_rank":21,"tier_absent_reason":"does-not-compete","source":"https://myoutislands.com/blog/boi-news/awaken-your-taste-buds-in-andros","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Sammy''s Bar and Grill","blurb":"Bahamas Out Island Promotion Board guide (April 27, 2018), Queen''s Highway, North Andros: \"you may want to taste the lobster bites, conch burger or conch salad\". A guide-site source: no own page found, and the 2018 date is stated","si":["culinary"],"commission":"venue","wells":["activities","eat"],"draw_rank":22,"tier_absent_reason":"does-not-compete","source":"https://myoutislands.com/blog/boi-news/awaken-your-taste-buds-in-andros","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)"},{"name":"Ezrena''s Restaurant","blurb":"Bahamas Out Island Promotion Board guide (April 27, 2018), Drigg''s Hill, South Andros: \"Be sure to try their boil fish and johnny cake! Eat authentic Bahamian food at Ezrena''s.\" A guide-site source: no own page found, and the 2018 date is stated","si":["culinary","culture"],"commission":"venue","wells":["activities","eat"],"draw_rank":23,"tier_absent_reason":"does-not-compete","source":"https://myoutislands.com/blog/boi-news/awaken-your-taste-buds-in-andros","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Western Air","blurb":"San Andros is \"Home of Western Air\" and \"just a 12 minute flight from Nassau & was the first airport Western Air began flights!\"; also serves Congo Town, which it calls \"the bone fishing capital of the world\"; booked at westernair.flythebahamas.com","si":["tropical"],"commission":"operator","wells":["activities","fly","move"],"draw_rank":24,"tier_absent_reason":"does-not-compete","source":"https://www.westernairbahamas.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Makers Air","blurb":"\"Scheduled and On-Demand Flights Across Florida and the Bahamas\" from Fort Lauderdale (2331 Northwest 55th Court) to San Andros, Fresh Creek and Congo Town; booked through a FareHarbor widget at book.makerssuite.com","si":["tropical","privatejet"],"commission":"operator","wells":["activities","fly","move","stay"],"draw_rank":25,"tier_absent_reason":"does-not-compete","source":"https://makersair.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"}],"faq":[{"q":"What is worth doing in Andros?","a":"Tongue of the Ocean wall dive — vertical wall at the 6,000-ft blue abyss edge.","source":"https://www.takeyourbackpack.com/backpacking-in-bahamas/visit-andros-barrier-reef/"},{"q":"How do I get to Andros Island from Nassau?","a":"By air. Small Hope Bay Lodge lists Titan Air, which \"Departs Nassau at 7 am & 4 pm and offers return flights (no flights on Saturday)\", and Le Air, which \"Departs Nassau at 6:45 am & 3 pm and offers return flights (no flights on Sunday)\", plus charter aircraft. Western Air says San Andros \"is just a 12 minute flight from Nassau\" and also serves Congo Town. The Titan Air and Le Air times are a lodge''s list, not the carriers'' timetables.","source":"https://www.smallhope.com/how-to-get-here","accessed":"2026-10-03"},{"q":"What are the airports on Andros Island?","a":"The Ministry of Tourism names three: San Andros Airport (SAQ) in North Andros near Nicholls Town, Andros Town International Airport (ASD) in Central Andros at Fresh Creek, and South Andros Airport (TZN) near Congo Town.","source":"https://www.bahamas.com/islands/andros","accessed":"2026-10-03"},{"q":"What is the best time to visit Andros Island, Bahamas?","a":"No page read names a best time, so none is given. What is published: NOAA says \"The Atlantic hurricane season runs from June 1 to November 30\" with a peak on September 10 and \"most activity occurring between mid-August and mid-October\". Small Hope Bay Lodge prices High Season as Feb 16-May 17 and Dec 16-Jan 5, and Low Season as Jan 6-Feb 15 and May 18-Dec 15 (https://www.smallhope.com/packages).","source":"https://www.nhc.noaa.gov/climo/","accessed":"2026-10-03"},{"q":"What are the blue holes of Andros, Bahamas?","a":"The Ministry of Tourism says \"Andros has more than 180 blue holes found inland and along its shore\" (https://www.bahamas.com/islands/andros). Blue Holes National Park in North Andros protects \"22 unique inland blue holes\", among them Captain Bill''s Blue Hole, \"nearly perfectly round\" with \"a depth of 100+ feet\". The park charges \"No entry fee\" but reads \"Closed temporarily\" on the Bahamas National Trust page read on 2026-10-03.","source":"https://bnt.bs/explore/andros/blue-holes-national-park/","accessed":"2026-10-03"},{"q":"Where should I stay in Andros, Bahamas?","a":"The Ministry of Tourism divides the island into North, Central and South Andros and Mangrove Cay. Lodges read for this build: in Central Andros, Small Hope Bay Lodge (all-inclusive, since 1960), Kamalame Cay (a private island) and Andros Island Bonefish Club at Cargill Creek; on Mangrove Cay, Mangrove Cay Club and Swain''s Cay Lodge; in South Andros, Andros Beach Club at Kemp''s Bay. Each is sourced on its own jewel in this dossier.","source":"https://www.bahamas.com/islands/andros","accessed":"2026-10-03"},{"q":"Are there all-inclusive resorts on Andros, Bahamas?","a":"Yes, on the pages read. Small Hope Bay Lodge''s all-inclusive covers \"All Meals and Open Bar\", bikes and kayaks, diving and snorkelling lessons, nature tours and babysitting, at a published adult rate of $375 per day in low season and $425 in high season. Andros Beach Club calls itself an \"all-inclusive boutique resort on South Andros Island\" (https://www.androsbeachclub.com/), and Kamalame Cay offers dining \"a la carte or all inclusive\" (https://www.kamalame.com/).","source":"https://www.smallhope.com/packages","accessed":"2026-10-03"},{"q":"When is the Andros Crab Fest?","a":"In June, at the \"Festival Site, Fresh Creek Central Andros\". The Ministry of Tourism''s news page gives \"June 13-14\" for the 18th edition of a festival that \"began in 1997\", and does not print the year. No 2026 or 2027 date was found on any page read.","source":"https://www.tourismtoday.com/news/catch-crabs-crawling","accessed":"2026-10-03"},{"q":"When is the Andros regatta?","a":"In July, at Morgan''s Bluff, North Andros, on the editions read. The Ministry of Tourism listed the All Andros & Berry Islands Regatta for July 9-11, 2020, at \"Regatta Village in Morgan''s Bluff\", with A, B and C class sloops; the 2019 edition ran July 4-7 (ewnews.com) and the 2023 All Andros Regatta July 13-16 alongside the Bahamas Games (The Tribune). No 2026 date was found.","source":"https://www.tourismtoday.com/events/all-andros-berry-islands-regatta","accessed":"2026-10-03"},{"q":"What is Andros known for?","a":"The Ministry of Tourism: \"The largest island in The Bahamas, Andros remains virtually untouched.\" It names more than 180 blue holes, the Andros Barrier Reef, bonefish flats, and Androsia batik at Fresh Creek, \"handmade batik since 1970s\" on its island page. Androsia''s own site says it was \"established by the Birch family in 1960\".","source":"https://www.bahamas.com/islands/andros","accessed":"2026-10-03"},{"q":"What are the restaurants on Andros, Bahamas?","a":"Hank''s Place on Queen''s Highway, Fresh Creek, has a \"dining room and bar built over the water\" and is \"Open Monday through Saturday 2:00 p.m.-10:00 p.m.\"; (242) 368-2447. A 2018 Out Islands guide also names Brigadier''s (Davis Creek), Shine''s Conch Shack (Mangrove Cay), Sammy''s Bar and Grill (North Andros) and Ezrena''s (Drigg''s Hill, South Andros) - https://myoutislands.com/blog/boi-news/awaken-your-taste-buds-in-andros.","source":"https://www.bahamas.com/vendor/hanks-place-restaurant-bar","accessed":"2026-10-03"},{"q":"How big is Andros?","a":"The Ministry of Tourism calls it \"The largest island in The Bahamas\" (https://www.bahamas.com/islands/andros). The Bahamas National Trust''s West Side National Park alone is \"1.5 million-acre\" and \"encompasses virtually the entire west side of Andros Island\". No total land area was read on a government page.","source":"https://bnt.bs/explore/andros/west-side-national-park/","accessed":"2026-10-03"}],"seo":{"meta_title":"Andros Bahamas: Barrier Reef, Wall & Blue Holes","meta_description":"Dive the world''s third-longest barrier reef, the Tongue of the Ocean wall and Andros blue holes from legacy dive lodges. When to go and how.","slug":"andros-bahamas","primary_keyword":"Andros barrier reef diving","long_tail":["Tongue of the Ocean wall dive","Andros blue holes diving","Small Hope Bay Lodge Andros","Andros bonefishing","Andros Bahamas diving"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-02","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-02","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-08-20T14:54:09Z","source_updated":"2026-05-28T17:01:45+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"diveglobal","status":"live"}],"ultra":null,"source_verified":"2026-07-02","hero":{"query":"Andros, Bahamas"},"geo":{"lat":24.4333,"lng":-77.95},"orbit":[{"id":"abaco-bahamas","jewels":3,"si":["tropical","yacht"]},{"id":"bimini-bahamas","jewels":3,"si":["diveglobal"]},{"id":"eleuthera-bahamas","jewels":3,"si":["tropical","diveglobal","expedition"]},{"id":"exuma-bahamas","jewels":3,"si":["expedition","liveaboard"]},{"id":"grand-bahama-freeport-bahamas"