  ('bimini-bahamas', '11C', 'Bimini', 'Bahamas', 'The hammerhead capital 50 miles off Miami', 'live', 'verified', 'oceanAerial', 'Bahamas', '{"diveglobal","wildlife","tropical","yacht","sports","culture","family"}', '{}', '{"premier","ultra"}', null, null, '{"key_facts":["Great hammerhead season Dec-Mar - world''s most reliable encounters (~20 ft)","Bull sharks Dec-Mar at baited ''Bull Run''","Sapona wreck - 1911 Ford concrete ship in ~20 ft (snorkel + dive)","Neal Watson''s Bimini Scuba Center + Bimini Big Game Club","Liveaboards route to Bimini but DEPART Freeport; malaria none; hurricane Jun-Nov peak Aug-Oct"],"safety":{"emergency":"911 / 919","hospital":"local clinic (Bimini); Nassau referral","malaria":"NONE","yellow_fever":"only if arriving from an endemic country","hurricane":"Jun-Nov, peak Aug-Oct","dive_no_fly":"18-24h (DAN)","firearms_ammo_law":"Bahamas ammo law applies — disclose","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-09-01T16:20:19Z","page_updated":"2026-05-28T17:01:45+01:00","source_country":"bahamas","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":null,"jewels":[{"name":"Great Hammerhead Shark Dive (Neal Watson''s Great Hammerhead Safari)","blurb":"Carried from the old dossier''s \"Great Hammerhead Shark Dive\" and now sourced to the operator''s own page; the season reads \"November through April\" there (the old line said Dec-Mar). Certified divers only, no cages, trips \"from 11am to 5pm\", \"Max 14 guests per trip\", \"$349 + 10% VAT (Incl. Tanks + Weights)\". \"Limited season. Limited spots.\"","si":["diveglobal","adventure","wildlife"],"commission":"operator","wells":["activities"],"draw_rank":1,"fit_rules":{"duration":"one day, \"from 11am to 5pm\"","before":"\"Certified Divers\" only","after":"back at the Big Game Club by 5pm","pairs_with":"Reef Shark Safari + Sapona Adventure from the same shop","time_season":"\"November through April\""},"tier_absent_reason":"does-not-compete","source":"https://www.biminiscubacenter.com/great-hammerheads","accessed":"2026-10-03"},{"name":"Bull Run (bull sharks)","blurb":"Carried from the old dossier and re-read. Bull Run has \"three pinnacles around a sandy floor\"; bull sharks appear most \"from December to March\" and reach \"up to 11 ft / 3.5m\" (Dive the World). What changed: the operator now names it on its own homepage as \"Bullrun Shark Cage experiences (for divers and non-divers)\" - a cage trip, not the old open baited dive; no Bull Run price was read on the operator''s pages.","si":["diveglobal","adventure","wildlife"],"commission":"operator","wells":["activities"],"draw_rank":4,"tier_absent_reason":"does-not-compete","source":"https://www.dive-the-world.com/diving-sites-bahamas-bimini.php","accessed":"2026-10-03"},{"name":"Sapona wreck (snorkel or dive)","blurb":"Carried from the old dossier and re-read. The Sapona was \"built in 1911 by Henry Ford\", 270 feet long, \"ran aground at Turtle Rocks in a hurricane in the late 1920s\", maximum depth 20 feet (Dive the World). What changed: now sold by the operator as the Reef Shark Safari + Sapona Adventure - \"one of Bimini''s most iconic dive sites\", with Caribbean reef and blacknose sharks; year-round; dive \"$160 + 10% VAT\", snorkel \"$120 adults / $90 kids + 10% VAT\" (https://www.biminiscubacenter.com/reef-sharks, read 2026-10-03).","si":["diveglobal","wildlife","family"],"commission":"operator","wells":["activities"],"draw_rank":5,"fit_rules":{"duration":"half-day boat trip","before":"certification for the dive; none for the snorkel","after":"snorkel guests have no dive restriction","pairs_with":"Great Hammerhead Safari (November through April)","time_season":"\"Year-Round\""},"tier_absent_reason":"does-not-compete","source":"https://www.dive-the-world.com/diving-sites-bahamas-bimini.php","accessed":"2026-10-03"},{"name":"Bimini Big Game Club Resort & Marina","blurb":"\"A boutique resort situated close to everything in Alice Town in North Bimini\", \"Founded in the 1930''s as an elegant dinner club and relocated and expanded in 1947 to its current home\". Islandview deluxe rooms, \"12 bungalow style cottages\" and two penthouse suites; \"75 slips and on-site Bahamian Customs and Immigration, accommodating boats up to 140 ft.\"; home to Neal Watson''s dive shop.","si":["yacht","diveglobal","sports","tropical"],"commission":"hotel","wells":["activities","eat","shop","stay"],"draw_rank":2,"tier_absent_reason":"not-established","source":"https://www.biggameclubbimini.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Wild Dolphin Safari (Neal Watson''s Bimini Scuba Center)","blurb":"\"No tanks. No tricks. Just you and a pod of wild dolphins in the open ocean.\" Snorkel-only, year-round, departing around 2pm and back around 5pm; \"$160 BSD + 10% VAT\" adults, \"$120 BSD + 10% VAT\" children, mask, fins and snorkel included.","si":["wildlife","family","tropical"],"commission":"operator","wells":["activities"],"draw_rank":3,"fit_rules":{"duration":"about 3 hours","before":"no certification - snorkel only","after":"back around 5pm","pairs_with":"Honeymoon Harbour Stingray Safari","time_season":"year-round"},"tier_absent_reason":"does-not-compete","source":"https://www.biminiscubacenter.com/wild-dolphins","accessed":"2026-10-03"},{"name":"Resorts World Bimini","blurb":"A \"750-acre beachfront resort\" on North Bimini with \"305 luxurious rooms\", \"2 remarkable pools, private beach, 10 varied restaurants, cafes and bars\", \"Casino Gaming\" and \"the largest marina complex in the Bahamas\"; part of Genting Americas (Genting Rewards). The hotel tower traded as a Hilton until 1 April 2025 (https://visitbimini.org/stay/hilton-at-resorts-world-bimini/, read 2026-10-03).","si":["tropical","entertainment","family","yacht"],"commission":"hotel","wells":["stay","eat","activities"],"draw_rank":6,"tier_absent_reason":"not-established","source":"https://rwbimini.com/hotel/","accessed":"2026-10-03"},{"name":"Honeymoon Harbour Stingray Safari","blurb":"\"Honeymoon Harbour is one of Bimini''s most beloved spots — a shallow, sandy cay where Southern Stingrays glide in waiting to say hello.\" Wade in from the beach or enter by boat; December through April; adults $120, children $90, plus 10% VAT, gear included.","si":["wildlife","family","tropical"],"commission":"operator","wells":["activities","gear","move","stay"],"draw_rank":7,"fit_rules":{"duration":"boat trip to the cay","before":"no certification - \"snorkelers of all skill levels\"","after":"back at Bimini Big Game Club","pairs_with":"Wild Dolphin Safari","time_season":"\"December through April\""},"tier_absent_reason":"does-not-compete","source":"https://www.biminiscubacenter.com/stingrays","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bimini Road","blurb":"\"Off Bimini''s northern coast lies this curious underwater rock formation: giant boulders, neatly laid.\" Dive the World (re-read 2026-10-03): \"weathered rocks\" like \"neatly cut blocks of a road\", maximum depth 20 feet, and it \"attracts Atlantic spotted dolphins\".","si":["culture","diveglobal","adventure"],"wells":["activities"],"draw_rank":8,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/islands/bimini","accessed":"2026-10-03","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Bimini Biological Field Station (Shark Lab) tours","blurb":"\"A 501 (c)(3) non-profit organization located on the island of South Bimini\", founded 1990 by Dr. Samuel Gruber. Tours are \"approximately 1.5 hours\" with \"a classroom presentation\", \"a short shark workup demonstration\" and, when possible, wild juvenile lemon sharks; \"Cash Donation - Suggested $20/per person\"; \"by appointment only\".","si":["wildlife","family","culture"],"wells":["activities","stay"],"draw_rank":9,"fit_rules":{"duration":"\"approximately 1.5 hours\"","before":"\"must be booked in advance\"","after":"South Bimini - the ferry back to North Bimini","pairs_with":"Great Hammerhead Safari","time_season":"\"Availability for tours is not always guaranteed\""},"tier_absent_reason":"not-sold","source":"https://www.biminisharklab.com/book-a-tour","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"venue (paid tour) - operator","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - the field station sells its own tours"},{"name":"Dolphin House Museum","blurb":"Founded by Sir Ashley B. Saunders - Bimini-born historian, author of the three-volume \"History of Bimini\", knighted in 2022 - who calls it \"a treasure of the Bahamas\". Visit Bimini lists it as \"a hand-built folk-art house and museum in Alice Town\" made from \"found objects, shells, and tile mosaics\", open Monday-Saturday 10AM-4PM, Sunday 11AM-4PM (https://visitbimini.org/do/dolphin-house/, read 2026-10-03).","si":["culture","senior","family"],"commission":"venue","wells":["activities","shop"],"draw_rank":10,"tier_absent_reason":"does-not-compete","source":"https://historyofbimini.com/","accessed":"2026-10-03"},{"name":"Radio Beach","blurb":"\"A public beach in Bimini, home to Sherry''s Paradise Beach Bar\", in Alice Town; the official site names \"three continuous beaches, including Radio Beach\".","si":["tropical","family"],"wells":["activities"],"draw_rank":11,"tier_absent_reason":"not-sold","source":"https://visitbimini.org/do/radio-beach/","accessed":"2026-10-03","commission":"entry non-commissionable (curated) - pair with a beach stay or boat day","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a beach - free; the stay and a boat day are the paid route"},{"name":"Westgate Bimini Bay","blurb":"\"A gated sanctuary of private villas and world-class marina access\" with balcony rooms, open-concept studios and two-bedroom villas, about 50 miles from Miami; \"Now Accepting Reservations\". Visit Bimini says Westgate took the property on and opened reservations \"for arrivals from 1 October 2026\" (https://visitbimini.org/stay/westgate-bimini-bay/, read 2026-10-03).","si":["family","tropical","yacht"],"commission":"hotel","wells":["activities","stay"],"draw_rank":12,"tier_absent_reason":"not-established","source":"https://www.westgateresorts.com/hotels/bahamas/bimini-bay/westgate-bimini-bay/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bimini Beach (Resorts World Bimini)","blurb":"\"Crystal-clear waters, white sand beaches, relaxing poolside moments, and vibrant energy\", with cabana rentals and beach-party tickets; day passes for non-hotel guests at the front desk, but \"Passes exclude cruise ship passengers\", and the beach is closed to all guests on Virgin Voyages port days.","si":["tropical","entertainment","family"],"commission":"venue","wells":["activities","eat","gear","move","stay"],"draw_rank":13,"tier_absent_reason":"does-not-compete","source":"https://rwbimini.com/bimini-beach/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bimini Native Fishing Tournament","blurb":"\"The first Bimini Native Fishing Tournament was held in the early 1950''s by a group of natives who organized the Progressive Sporting Club.\" Latest listed edition August 1-3, 2025, at Bimini Big Game Club: an opening ceremony, a full day and a half day of fishing, and an awards night. President Ken Stubbs, (242) 442-8939.","si":["sports","spectator","culture"],"commission":"venue","wells":["activities","stay"],"draw_rank":14,"tier_absent_reason":"does-not-compete","source":"https://tourismtoday.com/events/bimini-native-fishing-tournament","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bimini Homecoming","blurb":"\"Bimini''s biggest domestic event of the year\": \"seafood dishes, tropical drinks, Bahamian music, live entertainment, beach parties, and 4 days of fun\". Latest listed edition ended Apr 20, 2025, running from just before Good Friday to Easter Sunday at Administrator''s Yard, Alice Town; organised by Local Government, (242) 473-4174.","si":["culture","entertainment","family"],"wells":["activities","eat"],"draw_rank":15,"tier_absent_reason":"not-sold","source":"https://tourismtoday.com/events/bimini-homecoming-0","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"event (free to attend) - pair with Stay-Well and an event-week package","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a festival or regatta - free to attend; the stay and the package around it are the paid route"},{"name":"Resorts World Bimini Marina","blurb":"\"Located just steps from the resort and casino\", about 50 nautical miles from South Florida, with customs and immigration information on its site; neighbouring Bimini Bay Marina also offers slips (1-786-322-4440). Slip count and maximum length are not stated on the page.","si":["yacht","sports"],"commission":"venue","wells":["move","stay"],"draw_rank":16,"tier_absent_reason":"does-not-compete","source":"https://rwbimini.com/transportation/marina/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Tropic Ocean Airways seaplane, Fort Lauderdale to North Bimini","blurb":"\"Fort Lauderdale International (Sheltair) – FLL to Bimini (NSB)\", \"only a 25-minute flight from South Florida\", landing at \"North Bimini Seaplane Base (NSB)\"; scheduled flights and private charters.","si":["privatejet","tropical"],"commission":"operator","wells":["activities","fly","move"],"draw_rank":17,"tier_absent_reason":"does-not-compete","source":"https://flytropic.com/bimini/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Balearia Caribbean ferry, Fort Lauderdale to Bimini","blurb":"\"Balearia Caribbean''s ferry service\": \"Round trip services are only available out of Ft. Lauderdale''s – Port Everglades\", a \"quick two-hour ride to Bimini\"; Resorts World packages \"start at $299 per-person\" for summer sailings.","si":["ocean","tropical","family"],"commission":"operator","wells":["activities","move","stay"],"draw_rank":18,"tier_absent_reason":"does-not-compete","source":"https://rwbimini.com/transportation/ferry/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bimini Cruise Port and Fisherman''s Village","blurb":"The port \"opened in 2021\" and has \"welcomed over one million cruise passengers\"; a complimentary tram runs \"every 10-15 minutes\" to Fisherman''s Village, an open-air marketplace with shops, a pizzeria, gelateria and the Healing Hole restaurant. Lines calling: Virgin Voyages, Carnival, Celebrity, Royal Caribbean, Holland America and Norwegian.","si":["tropical","family","group"],"commission":"venue","wells":["activities","eat","move","shop","stay"],"draw_rank":19,"tier_absent_reason":"does-not-compete","source":"https://rwbimini.com/cruise-port/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bimini Seafood Company & Conch Bar","blurb":"One of two restaurants at Bimini Big Game Club; Visit Bimini: serving \"Bahamian and American dishes for breakfast, lunch, and dinner\" (https://visitbimini.org/eat/bimini-seafood-company-conch-bar/, read 2026-10-03).","si":["culinary","yacht"],"commission":"venue","wells":["activities","eat"],"draw_rank":20,"tier_absent_reason":"does-not-compete","source":"https://www.biggameclubbimini.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Hemingways Poolside Rum Club (Bimini Big Game Club)","blurb":"The Big Game Club''s \"poolside rum club\"; Visit Bimini: a \"Poolside bar at Bimini Big Game Club with large Caribbean rum selection\" (https://visitbimini.org/eat/hemingways-poolside-rum-club/, read 2026-10-03).","si":["culinary","romance","culture"],"commission":"venue","wells":["activities","eat"],"draw_rank":21,"tier_absent_reason":"does-not-compete","source":"https://www.biggameclubbimini.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)"},{"name":"The Tides (Resorts World Bimini)","blurb":"\"Enjoy a daily breakfast buffet and a full lunch and dinner menu featuring fresh seafood, pastas, wood-fire grilled pizzas\"; one of nine venues listed with The Sushi Bar, Hemingway''s, Amicci''s, Beach Club 360 and the Healing Hole.","si":["culinary","family"],"commission":"venue","wells":["activities","eat","stay"],"draw_rank":22,"tier_absent_reason":"does-not-compete","source":"https://rwbimini.com/dining/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Joe''s Conch Stand","blurb":"\"Joe dives his own conch — as many as 300 a day in season — and cracks it to order.\" Bailey Town; closed Monday, Tue-Thu 10AM-5PM, Fri-Sat 10AM-6PM, Sun 10AM-5PM; +1 242-554-6183.","si":["culinary","culture"],"commission":"venue","wells":["activities","eat"],"draw_rank":23,"tier_absent_reason":"does-not-compete","source":"https://visitbimini.org/eat/joes-conch-stand/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)"},{"name":"Stuart''s Conch Salad Stand","blurb":"\"A Bailey Town conch salad stand described as the most popular stop with visitors\"; +1 242-347-2474.","si":["culinary","culture"],"commission":"venue","wells":["activities","eat"],"draw_rank":24,"tier_absent_reason":"does-not-compete","source":"https://visitbimini.org/eat/stuarts-conch-salad-stand/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)"},{"name":"The End of the World Bar & Saloon","blurb":"\"The sand-floor waterfront saloon that anchors Alice Town''s bar history\"; \"Hours are famously irregular.\"","si":["culinary","culture","entertainment"],"commission":"venue","wells":["activities","eat"],"draw_rank":25,"tier_absent_reason":"does-not-compete","source":"https://visitbimini.org/eat/end-of-the-world-bar/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)"},{"name":"Big John''s Hotel & Conch Shell Bar","blurb":"\"Seven renovated rooms above the bar and restaurant in Alice Town\"; the bar has \"live music on Friday and Saturday nights\" (https://visitbimini.org/eat/big-johns-conch-shell-bar/, read 2026-10-03). +1 242-347-3117.","si":["entertainment","culinary","tropical"],"commission":"hotel","wells":["activities","eat","stay"],"draw_rank":26,"tier_absent_reason":"not-established","source":"https://visitbimini.org/stay/big-johns-hotel-lounge/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bimini Cove Resort & Marina (formerly Bimini Sands)","blurb":"\"A South Bimini resort formerly branded Bimini Sands Resort & Marina; both names still circulate online.\" 1 Beach Road, South Bimini, Port Royal; +1 833-246-4643. biminisands.com now redirects to a domain-for-sale page and biminicoveresort.com returned HTTP 403 when read.","si":["yacht","tropical","family"],"commission":"hotel","wells":["activities","stay"],"draw_rank":27,"tier_absent_reason":"not-established","source":"https://visitbimini.org/stay/bimini-cove-resort-marina/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Adrenaline Adventures (sportfishing charter)","blurb":"\"Fishing charter operating the 50-foot Sportsfish \"Jezebel\" out of Bimini Big Game Club\", running 4/6/8-hour deep-sea trips \"over drop-offs past 2,500 ft for marlin, tuna, sailfish, wahoo, and mahi-mahi\"; the listing says \"bareboat charters start around $1,200\".","si":["sports","ocean","adventure"],"commission":"operator","wells":["activities"],"draw_rank":28,"tier_absent_reason":"does-not-compete","source":"https://visitbimini.org/fish/adrenaline-adventures/","accessed":"2026-10-03"},{"name":"\"Bonefish\" Ebbie David, flats guide","blurb":"\"Certified bonefish guide with more than 20 years of experience on Bimini''s flats\", Bailey Town; +1 242-347-2053.","si":["sports","ocean","adventure"],"commission":"guide","wells":["activities"],"draw_rank":29,"tier_absent_reason":"does-not-compete","source":"https://visitbimini.org/fish/ebbie-david/","accessed":"2026-10-03"},{"name":"Slicker Wahoo Bimini Tournament","blurb":"\"Happening on December 7th, 2024 at the legendary Bimini Big Game Club!\" 6:45am-4pm, \"$1,500 general entry fee\", weigh-in at Bimini Big Game Club.","si":["sports","yacht","spectator"],"commission":"venue","wells":["activities"],"draw_rank":30,"tier_absent_reason":"does-not-compete","source":"https://tourismtoday.com/events/slicker-wahoo-tournament-2024","accessed":"2026-10-03"},{"name":"Healing Hole","blurb":"\"A sulfur spring deep in the mangroves of Bonefish Creek, reachable by kayak, with a folk belief that it treats arthritis and gout.\" The listing says its details \"could not be independently verified\".","si":["adventure","wellness","culture"],"wells":["activities"],"draw_rank":31,"tier_absent_reason":"not-sold","source":"https://visitbimini.org/do/healing-hole/","accessed":"2026-10-03","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Fountain of Youth (South Bimini)","blurb":"\"A limestone well near the South Bimini airport, near where Ponce de León reputedly searched for the fountain of youth in 1513.\"","si":["culture","family"],"wells":["activities","fly"],"draw_rank":32,"tier_absent_reason":"not-sold","source":"https://visitbimini.org/do/fountain-of-youth/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"Bimini Blue Adventures","blurb":"\"Boat excursion operator in Bailey Town running reef shark snorkeling trips, stingray encounters, and visits to the SS Sapona wreck\", daily 8:00 AM-5:00 PM, +1 242-827-7772. Its own site biminiblueadventures.com carried template placeholder text when read, with a Book Now link to Peek.","si":["ocean","wildlife","family"],"commission":"operator","wells":["activities","move"],"draw_rank":33,"tier_absent_reason":"does-not-compete","source":"https://visitbimini.org/do/bimini-blue-adventures/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"}],"faq":[{"q":"What is worth doing in Bimini?","a":"Great Hammerhead Shark Dive — face-to-face with 15-20 ft great hammerheads.","source":"https://www.dive-the-world.com/diving-sites-bahamas-bimini.php"},{"q":"How do I get to Bimini from Fort Lauderdale?","a":"By ferry or seaplane. Resorts World Bimini: \"Balearia Caribbean''s ferry service\" - \"Round trip services are only available out of Ft. Lauderdale''s – Port Everglades\", a \"quick two-hour ride to Bimini\". Tropic Ocean Airways flies \"Fort Lauderdale International (Sheltair) – FLL to Bimini (NSB)\", \"only a 25-minute flight from South Florida\" (https://flytropic.com/bimini/, read 2026-10-03).","source":"https://rwbimini.com/transportation/ferry/","accessed":"2026-10-03"},{"q":"How do I get to Bimini from Miami?","a":"American Airlines flies from its Miami hub to South Bimini: \"New three-times-weekly service from American''s Miami hub\", operating \"on Mondays, Wednesdays, and Saturdays\" with an Embraer E175. Westgate Bimini Bay describes \"direct flight from Miami (about 30 minutes)\" (https://www.westgateresorts.com/hotels/bahamas/bimini-bay/westgate-bimini-bay/, read 2026-10-03).","source":"https://airlinegeeks.com/2025/09/06/american-adding-new-international-airport/","accessed":"2026-10-03"},{"q":"How long is the ferry to Bimini?","a":"About two hours from Fort Lauderdale. Resorts World Bimini calls Balearia Caribbean''s crossing from Port Everglades a \"quick two-hour ride to Bimini\".","source":"https://rwbimini.com/transportation/ferry/","accessed":"2026-10-03"},{"q":"When is the best time to see hammerheads in Bimini?","a":"Neal Watson''s Bimini Scuba Center runs its Great Hammerhead Safari \"November through April\" for certified divers - \"Limited season. Limited spots.\" Dive the World gives great hammerhead season as \"January to March\" (https://www.dive-the-world.com/diving-sites-bahamas-bimini.php, read 2026-10-03).","source":"https://www.biminiscubacenter.com/great-hammerheads","accessed":"2026-10-03"},{"q":"When is the best time to see dolphins in Bimini?","a":"Neal Watson''s Wild Dolphin Safari runs year-round, a snorkel trip of about three hours leaving around 2pm: \"No tanks. No tricks. Just you and a pod of wild dolphins in the open ocean.\"","source":"https://www.biminiscubacenter.com/wild-dolphins","accessed":"2026-10-03"},{"q":"When is Bimini Homecoming?","a":"Around Easter. The Ministry of Tourism''s latest listed edition ran four days to Apr 20, 2025, beginning just before Good Friday and ending on Easter Sunday, at Administrator''s Yard, Alice Town, organised by Local Government ((242) 473-4174). No 2026 or 2027 date was found.","source":"https://tourismtoday.com/events/bimini-homecoming-0","accessed":"2026-10-03"},{"q":"What is there to do in the Bimini cruise port?","a":"A complimentary tram runs \"every 10-15 minutes\" from the ships to Fisherman''s Village, an open-air marketplace with shops, a pizzeria, gelateria and the Healing Hole restaurant, plus pools and water sports. Virgin Voyages guests get the Beach Club as a complimentary private destination; Resorts World''s Bimini Beach day passes \"exclude cruise ship passengers\" (https://rwbimini.com/bimini-beach/, read 2026-10-03).","source":"https://rwbimini.com/cruise-port/","accessed":"2026-10-03"},{"q":"Do you need cash in Bimini?","a":"The official tourism site: \"While certain places do take credit cards, it''s advised that you carry cash if you''re exploring the Out Islands.\" \"The Bahamian dollar is maintained at the same level as the U.S. dollar and both are accepted interchangeably on all islands.\"","source":"https://www.bahamas.com/faq","accessed":"2026-10-03"},{"q":"Can you snorkel Bimini Road?","a":"Dive the World gives Bimini Road a maximum depth of 20 feet and says it attracts Atlantic spotted dolphins. Westgate Bimini Bay lists \"snorkeling at the Road to Atlantis\" among its activities (https://www.westgateresorts.com/hotels/bahamas/bimini-bay/westgate-bimini-bay/, read 2026-10-03).","source":"https://www.dive-the-world.com/diving-sites-bahamas-bimini.php","accessed":"2026-10-03"},{"q":"Do you need a passport for a Bimini cruise?","a":"Holland America Line, which calls at Bimini: \"For U.S. citizens, a valid U.S. Passport is essential for re-entry into the United States.\" It adds that \"voter registration or a certified birth certificate is no longer accepted as proof of U.S. citizenship.\"","source":"https://www.hollandamerica.com/en/cruise-destinations/caribbean-cruises/travel-articles/bahamas-travel-requirements","accessed":"2026-10-03"}],"seo":{"meta_title":"Bimini Bahamas: Hammerhead & Bull Shark Diving","meta_description":"Dive with great hammerheads and bull sharks in Bimini, explore the Sapona wreck and big-game fish the Bahamas. Season timing and how.","slug":"bimini-bahamas","primary_keyword":"Bimini great hammerhead shark dive","long_tail":["Bimini bull shark diving Bull Run","Sapona wreck Bimini","Neal Watson Bimini Scuba Center","Bimini big game fishing","Bimini shark season"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-02","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-02","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-08-20T14:54:09Z","source_updated":"2026-05-28T17:01:45+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"diveglobal","status":"live"}],"ultra":null,"source_verified":"2026-07-02","hero":{"query":"Bimini, Bahamas"},"geo":{"lat":25.7333,"lng":-79.25},"orbit":[{"id":"abaco-bahamas","jewels":3,"si":["tropical","yacht"]},{"id":"andros-bahamas","jewels":3,"si":["diveglobal"]},{"id":"eleuthera-bahamas","jewels":3,"si":["tropical","diveglobal","expedition"]},{"id":"exuma-bahamas","jewels":3,"si":["expedition","liveaboard"]},{"id":"grand-bahama-freeport-bahamas","jewels":3,"si":["diveglobal","liveaboard","expedition"]},{"id":"harbour-island-bahamas","jewels":3,"si":["tropical","ultra","culture"]},{"id":"long-island-bahamas","jewels":3,"si":["tropical","expedition","diveglobal"]},{"id":"nassau-paradise-island-bahamas","jewels":3,"si":["romance","diveglobal","liveaboard"]}],"orbit_country":[]}'::jsonb, 20),
