ier_absent_reason":"not-established","source":"https://www.pineapplefields.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"1648: An Island Restaurant","blurb":"the waterfront restaurant of French Leave Resort, Governor''s Harbour","si":["culinary","romance"],"commission":"venue","wells":["eat","stay"],"draw_rank":22,"tier_absent_reason":"not-sold","source":"https://www.frenchleaveresort.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Freedom Restaurant & Sushi Bar at The Cove","blurb":"The Cove''s restaurant with sushi bar, alongside the Gregory Town Grill and Point Bar","si":["culinary","romance"],"commission":"venue","wells":["activities","eat"],"draw_rank":23,"tier_absent_reason":"not-sold","source":"https://www.thecoveeleuthera.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"The Island School and Cape Eleuthera Institute","blurb":"on Cape Eleuthera, which \"sits on the edge of the Exuma Sound where the Bahamas shelf drops thousands of feet into the Atlantic Ocean\"; a research hub and school with visiting programmes for student groups; tours by contacting (242) 334-8551 or info@islandschool.org","si":["deepdive","family","wildlife","ocean"],"commission":"venue","wells":["activities"],"draw_rank":24,"tier_absent_reason":"not-sold","source":"https://islandschool.org/","accessed":"2026-10-02"},{"name":"Savannah Sound Homecoming","blurb":"Jul 7-11, 2027; \"a great way to welcome many domestic and international visitors during The Bahamas Independence week\"","si":["culture","family","entertainment"],"wells":["activities"],"draw_rank":25,"tier_absent_reason":"not-sold","source":"https://www.tourismtoday.com/events?page=1","accessed":"2026-10-02","commission":"event (free to attend) - pair with Stay-Well and an event-week package","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a festival or regatta - free to attend; the stay and the package around it are the paid route"},{"name":"Paul Petty, fishing guide","blurb":"Wikivoyage''s Do list names \"Paul Petty as a good local fishing guide\"","si":["ocean","sports"],"commission":"guide","wells":["activities"],"draw_rank":26,"tier_absent_reason":"does-not-compete","source":"https://en.wikivoyage.org/wiki/Eleuthera","accessed":"2026-10-02"},{"name":"Hut Pointe Inn","blurb":"\"large, air-conditioned, 2 bedroom suites with fully equipped kitchens\" from 800 to 1,200 square feet on Queens Highway, Governors Harbour","si":["family","tropical","group"],"commission":"hotel","wells":["stay"],"draw_rank":27,"tier_absent_reason":"not-established","source":"https://www.hutpointe.com/","accessed":"2026-10-02"},{"name":"Back to The Bay, Tarpum Bay","blurb":"Jul 28-Aug 2, 2027; \"live entertainment, junkanoo rush-outs, and delicious native dishes\"","si":["culture","entertainment","culinary"],"wells":["activities","eat"],"draw_rank":28,"tier_absent_reason":"not-sold","source":"https://www.tourismtoday.com/events?page=1","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — food SI (David 2026-10-05: every traveler has to eat)","commission":"event (free to attend) - pair with Stay-Well and an event-week package","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a festival or regatta - free to attend; the stay and the package around it are the paid route"},{"name":"Bayfest, Hatchet Bay","blurb":"Jul 28-Aug 2, 2027; \"live entertainment by Bahamian Artists, fashion shows, and various competitions\"","si":["culture","entertainment"],"wells":["activities","stay"],"draw_rank":29,"tier_absent_reason":"not-sold","source":"https://www.tourismtoday.com/events?page=1","accessed":"2026-10-02","commission":"event (free to attend) - pair with Stay-Well and an event-week package","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a festival or regatta - free to attend; the stay and the package around it are the paid route","wells_basis":"full pass 2026-10-05, additive — commission lane ''event (free to attend) - pair with stay-''"},{"name":"Bannerman Town Festival","blurb":"Jul 31-Aug 2, 2027; \"delicious native food, ice-cold beverages, desserts, live entertainment, and games\"","si":["culture","culinary","family"],"wells":["activities","eat"],"draw_rank":30,"tier_absent_reason":"not-sold","source":"https://www.tourismtoday.com/events?page=1","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text","commission":"event (free to attend) - pair with Stay-Well and an event-week package","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a festival or regatta - free to attend; the stay and the package around it are the paid route"},{"name":"Buccaneer Club Restaurant","blurb":"Governor''s Harbour; \"Breakfast, lunch and dinner 7 days a week\"","si":["culinary","family"],"commission":"venue","wells":["eat"],"draw_rank":31,"tier_absent_reason":"not-sold","source":"https://en.wikivoyage.org/wiki/Eleuthera","accessed":"2026-10-02"},{"name":"Sammy''s Place","blurb":"Rock Sound; \"Very reasonably priced and good local food\"; +1 242-334-2121","si":["culinary","family"],"commission":"venue","wells":["eat"],"draw_rank":32,"tier_absent_reason":"not-sold","source":"https://en.wikivoyage.org/wiki/Eleuthera","accessed":"2026-10-02"},{"name":"Mate & Jenny''s Pizza Restaurant & Bar","blurb":"South Palmetto Point; +1 242-332-1504","si":["culinary","family"],"commission":"venue","wells":["eat"],"draw_rank":33,"tier_absent_reason":"not-sold","source":"https://en.wikivoyage.org/wiki/Eleuthera","accessed":"2026-10-02"},{"name":"LeoRose Sunset Beach Bar & Grill","blurb":"Queen''s Highway, across from the pier in James Cistern; \"Basic local bar, cold beer and good Bahamian food\"; +1 242-335-6223","si":["culinary","culture"],"commission":"venue","wells":["activities","eat"],"draw_rank":34,"tier_absent_reason":"not-sold","source":"https://en.wikivoyage.org/wiki/Eleuthera","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Island Farm","blurb":"Queen''s Highway, \".5 miles south of Palmetto Point Crossroads\"; \"fresh bread baked on the premises, fresh produce, greens and herbs, jams, jellies\"; +1 242-332-0141","si":["culinary","family"],"commission":"venue","wells":["shop","eat"],"draw_rank":35,"tier_absent_reason":"not-sold","source":"https://en.wikivoyage.org/wiki/Eleuthera","accessed":"2026-10-02"}],"faq":[{"q":"What is worth doing in Eleuthera?","a":"Pink Sands Beach (Harbour Island) — rose sand that glows at sunset.","source":"https://www.bahamas.com/islands/eleuthera-harbour-island/pink-sands-beach"},{"q":"How do I get to Eleuthera from Nassau?","a":"By air or by ferry. The Ministry of Tourism lists Bahamasair (\"multiple daily scheduled flights from Nassau (NAS) to North Eleuthera (ELH) and Governor''s Harbour (GHB)\"), Western Air, LeAir, Pineapple Air (flight times \"around 20-25 minutes\") and Southern Air Charter. By sea, Bahamas Ferries, Current Pride, MV Daybreak and Island Link run between Nassau and parts of Eleuthera, \"Around 2.5 to 3 hours\".","source":"https://www.bahamas.com/islands/eleuthera-harbour-island/getting-to-eleuthera-harbour-island","accessed":"2026-10-02"},{"q":"How do I get to Eleuthera from Fort Lauderdale?","a":"Tradewind Aviation flies scheduled service to North Eleuthera from Fort Lauderdale (FLL) and Stuart (SUA) in a Pilatus PC-12; the carrier gives the Fort Lauderdale flight time as 54 minutes. The Ministry of Tourism also lists Aztec Airways, Makers Air and Tropic Ocean Airways from FLL to ELH.","source":"https://www.flytradewind.com/destination/north-eleuthera/","accessed":"2026-10-02"},{"q":"What is the Eleuthera airport code?","a":"Eleuthera has more than one airport. The Ministry of Tourism uses ELH for North Eleuthera and GHB for Governor''s Harbour; the island also has Rock Sound International Airport.","source":"https://www.bahamas.com/islands/eleuthera-harbour-island/getting-to-eleuthera-harbour-island","accessed":"2026-10-02"},{"q":"When is the Eleuthera Pineapple Festival?","a":"The next edition is listed for \"Jun 04, 2027 - Jun 05, 2027\" on Queen''s Highway, Gregory Town. The festival is \"a yearly celebration in the Gregory Town, Eleuthera area\" when \"descendants return home to visit relatives and friends\". The 2026 edition, the 37th, ran 5-6 June 2026.","source":"https://www.bahamas.com/events/pineapple-festival","accessed":"2026-10-02"},{"q":"When is the Eleuthera homecoming?","a":"Several settlements hold their own. The Ministry''s listings give Savannah Sound Homecoming Jul 7-11, 2027, Back to The Bay in Tarpum Bay and Bayfest in Hatchet Bay both Jul 28-Aug 2, 2027, and the Bannerman Town Festival Jul 31-Aug 2, 2027.","source":"https://www.tourismtoday.com/events?page=1","accessed":"2026-10-02"},{"q":"How long is the island of Eleuthera?","a":"The Ministry of Tourism gives it as \"180 km long, and little more than 1.6 km wide in certain spots\", \"A pencil-thin island with 210 miles of coastline\".","source":"https://www.bahamas.com/islands/eleuthera-harbour-island","accessed":"2026-10-02"},{"q":"What is the best time to visit Eleuthera?","a":"PADI''s guide says \"November to May is the dry season in Eleuthera and Harbour Island\", with the best shark encounters in those months. It does not name a single best month. NOAA''s Atlantic hurricane season runs June 1 to November 30 (see the timing section).","source":"https://www.padi.com/diving-in/eleuthera-harbour-island/","accessed":"2026-10-02"},{"q":"What is there to do in Eleuthera?","a":"The Ministry of Tourism names the Glass Window Bridge, Queen''s Bath, Ocean Hole in Rock Sound (\"seemingly bottomless inland blue hole\"), Surfer''s Beach, Lighthouse Beach, diving wrecks and reefs, island hopping among the cays, horseback riding on beaches, and the Pineapple Fest in June.","source":"https://www.bahamas.com/islands/eleuthera-harbour-island","accessed":"2026-10-02"},{"q":"Where should I stay in Eleuthera?","a":"The Ministry says: \"From intimate resorts and friendly, affordable inns to ultra-luxurious oceanfront cottages, it is impossible to go wrong on Eleuthera & Harbour Island.\" This dossier''s stay section names The Cove in Gregory Town, French Leave Resort in Governor''s Harbour, Cape Eleuthera Resort & Marina in the south, and villas and condos at Sky Beach Club, Pineapple Fields and Hut Pointe Inn.","source":"https://www.bahamas.com/islands/eleuthera-harbour-island/where-to-stay","accessed":"2026-10-02"},{"q":"How do I get around Eleuthera?","a":"Wikivoyage lists car hire (Eleuthera Car Rental by Gateway) and notes the Queen''s Highway is \"well paved (watch out for road repairs north of Governor''s Harbour airport)\". For cyclists it calls Eleuthera, \"with its rolling hills (and three killers around Gregory Town)\", \"the most challenging island\".","source":"https://en.wikivoyage.org/wiki/Eleuthera","accessed":"2026-10-02"}],"seo":{"meta_title":"Eleuthera Bahamas: Pink Sands, Reefs & Calm","meta_description":"Discover Eleuthera & Harbour Island — pink-sand beaches, Glass Window Bridge, reef diving and barefoot luxury in the Bahamas Out Islands. When and how.","slug":"eleuthera-bahamas","primary_keyword":"Eleuthera diving","long_tail":["Pink Sands Beach Harbour Island","Glass Window Bridge Bahamas","Eleuthera honeymoon resorts","Devil''s Backbone reef","Ocean Hole Rock Sound"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-02","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-02","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-08-20T14:54:09Z","source_updated":"2026-05-28T17:01:45+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"diveglobal","status":"live"},{"si":"expedition","status":"live"}],"ultra":null,"source_verified":"2026-07-02","hero":{"query":"Eleuthera, Bahamas"},"geo":{"lat":25.15,"lng":-76.15},"orbit":[{"id":"abaco-bahamas","jewels":3,"si":["tropical","yacht"]},{"id":"andros-bahamas","jewels":3,"si":["diveglobal"]},{"id":"bimini-bahamas","jewels":3,"si":["diveglobal"]},{"id":"exuma-bahamas","jewels":3,"si":["expedition","liveaboard"]},{"id":"grand-bahama-freeport-bahamas","jewels":3,"si":["diveglobal","liveaboard","expedition"]},{"id":"harbour-island-bahamas","jewels":3,"si":["tropical","ultra","culture"]},{"id":"long-island-bahamas","jewels":3,"si":["tropical","expedition","diveglobal"]},{"id":"nassau-paradise-island-bahamas","jewels":3,"si":["romance","diveglobal","liveaboard"]}],"orbit_country":[]}'::jsonb, 36),
